package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {





































    @Test
    public void testCreateNumber_EdgeCases() {
        // Test all zeros logic
        Number n = NumberUtils.createNumber("0.00000000000000000000");
        assertTrue(n instanceof BigDecimal);

        // Test large hex with specific digit threshold
        // 16 hex digits, first is '8' -> should be Long or BigInt depending on implementation logic
        Number nHex = NumberUtils.createNumber("0x8000000000000000");
        assertTrue(nHex instanceof Long || nHex instanceof BigInteger);
    }


}

